begin;
create extension if not exists pgtap with schema extensions;
create temporary table auto_tap(result text) on commit drop;
create temporary table auto_context(actor uuid,shop uuid,store_id uuid,tid uuid,qr uuid,epoch uuid,product uuid,guest uuid,key uuid,token uuid,bill uuid,order_id uuid,fp text) on commit drop;
do $$
declare a uuid; s uuid:=gen_random_uuid(); cat uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); t uuid; ss uuid;
begin
 select user_id into strict a from public.shop_members where role='OWNER' and status='ACTIVE' limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 t:=public.save_dining_table(s,'Auto table'); ss:=(public.open_store_session(s)->>'id')::uuid;
end $$;
create function pg_temp.auto_order(lat double precision default 16, request_key uuid default null, customer uuid default null, token_override uuid default null)
returns jsonb language sql as $$
 select public.create_auto_table_qr_order(shop,qr,epoch,coalesce(customer,guest),coalesce(request_key,key),coalesce(token_override,token),lat,103,10,now(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',1))) from auto_context;
$$;
update auto_context set bill=(public.get_dining_table_context(qr)->>'billId')::uuid,order_id=(pg_temp.auto_order()->>'orderId')::uuid;
select public.set_table_bill_checkout(bill,true) from auto_context;
update auto_context set fp=public.get_table_bill(bill)->>'fingerprint';
select public.pay_table_bill(bill,'BANK_TRANSFER',7800,gen_random_uuid(),fp) from auto_context;
select public.update_order_status(id,status,'COMPLETED') from public.orders where table_bill_id=(select bill from auto_context);
update auto_context set epoch=(public.get_dining_table_context(qr)->>'tableEpoch')::uuid;
select public.set_store_order_acceptance(shop,store_id,false) from auto_context;
select public.set_store_order_acceptance(shop,store_id,true) from auto_context;
select result from auto_tap;
rollback;
