insert into auto_tap select no_plan();
 insert into public.shops(id,name,created_by) values(s,'Auto table QA',a);
 insert into public.shop_members(shop_id,user_id,role,granted_by) values(s,a,'OWNER',a);
 insert into public.shop_locations(shop_id,latitude,longitude) values(s,16,103);
 insert into public.categories(id,shop_id,name) values(cat,s,'QA');
 insert into public.products(id,shop_id,category_id,name,base_price_satang) values(p,s,cat,'Kebab',3900);
 insert into auto_context select a,s,ss,t,qr_token,ordering_epoch,p,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null,null from public.dining_tables where id=t;
insert into auto_tap select ok(not has_function_privilege('anon','public.create_auto_table_qr_order(uuid,uuid,uuid,uuid,uuid,uuid,double precision,double precision,double precision,timestamptz,jsonb,text)','EXECUTE'),'anonymous cannot bypass checkout Edge');
insert into auto_tap select ok(not has_function_privilege('authenticated','public.create_auto_table_qr_order(uuid,uuid,uuid,uuid,uuid,uuid,double precision,double precision,double precision,timestamptz,jsonb,text)','EXECUTE'),'staff cannot bypass customer geofence Edge');
insert into auto_tap select is(public.get_dining_table_context((select qr from auto_context))->>'acceptingOrders','true','empty table accepts ordering while shop open');
insert into auto_tap select is((select count(*)::integer from public.table_bills where shop_id=(select shop from auto_context)),0,'reading menu never creates empty bill');
insert into auto_tap select throws_ok($$select pg_temp.auto_order(17)$$,'42501','Customer is outside the ordering area.','invalid geofence rolls back automatic round');
insert into auto_tap select is((select count(*)::integer from public.table_sessions where shop_id=(select shop from auto_context)),0,'failed first checkout leaves no table session');
insert into auto_tap select lives_ok($$select pg_temp.auto_order()$$,'first checkout opens round and creates order');
insert into auto_tap select is((select count(*)::integer from public.table_bills where shop_id=(select shop from auto_context)),1,'response lost retry does not create another bill');
insert into auto_tap select is((select count(*)::integer from public.orders where table_bill_id=(select bill from auto_context)),1,'response lost retry does not duplicate order');
insert into auto_tap select is(pg_temp.auto_order()->>'tableBillId',(select bill::text from auto_context),'checkout returns real bill identity');
insert into auto_tap select is(jsonb_array_length(public.list_active_staff_orders((select shop from auto_context))->'orders'),1,'first automatic QR order appears in staff queue');
insert into auto_tap select is(public.list_active_staff_orders((select shop from auto_context))->'orders'->0->>'tableBillId',(select bill::text from auto_context),'staff queue links the real automatic bill');
insert into auto_tap select is(public.list_active_staff_orders((select shop from auto_context))->'orders'->0->>'tableName','Auto table','staff queue includes table name');
insert into auto_tap select is(public.list_active_staff_orders((select shop from auto_context))->'orders'->0->>'status','QUEUED','new table order starts waiting for preparation');
insert into auto_tap select is(public.list_active_staff_orders((select shop from auto_context))->'orders'->0->>'source','QR','staff queue identifies QR source');
insert into auto_tap select is(public.list_active_staff_orders((select shop from auto_context))->'orders'->0->'items'->0->>'name','Kebab','kitchen receives menu item details');
insert into auto_tap select is(public.list_active_staff_orders((select shop from auto_context))->'orders'->0->>'totalSatang','3900','kitchen queue receives authoritative total');
insert into auto_tap select lives_ok($$select pg_temp.auto_order(16,gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'second device joins same epoch');
insert into auto_tap select is(jsonb_array_length(public.list_active_staff_orders((select shop from auto_context))->'orders'),2,'another order round adds another kitchen queue ticket');
insert into auto_tap select is((select count(distinct table_bill_id)::integer from public.orders where shop_id=(select shop from auto_context)),1,'all devices share one active bill');
insert into auto_tap select is(public.get_table_bill((select bill from auto_context))->>'totalSatang','7800','combined bill prices authoritative');
insert into auto_tap select is((select count(*)::integer from public.audit_logs where shop_id=(select shop from auto_context) and action='DINING_TABLE_AUTO_OPENED'),1,'one automatic opening audit');
insert into auto_tap select is((select opened_by from public.table_sessions where table_id=(select tid from auto_context)),null::uuid,'customer auto opening does not impersonate staff');
insert into auto_tap select throws_ok($$select pg_temp.auto_order(16,gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'P0001','Table is not accepting orders.','frozen bill rejects new orders');
insert into auto_tap select is(public.track_table_round((select guest from auto_context))->>'status','PAID','old link shows paid immediately');
insert into auto_tap select is(public.get_table_bill((select bill from auto_context))->>'closed','false','paid table with pending food not reused');
insert into auto_tap select is(jsonb_array_length(public.list_active_staff_orders((select shop from auto_context))->'orders'),2,'payment does not hide unfinished food from kitchen');
insert into auto_tap select is(jsonb_array_length(public.list_active_staff_orders((select shop from auto_context))->'orders'),0,'settled completed food leaves active kitchen queue');
insert into auto_tap select is(public.get_table_bill((select bill from auto_context))->>'closed','true','last dish completion automatically frees settled table');
insert into auto_tap select is(public.get_dining_table_context((select qr from auto_context))->>'billId',null::text,'static QR now has no active bill');
insert into auto_tap select is(public.get_dining_table_context((select qr from auto_context))->>'acceptingOrders','true','table ready for next guests without staff opening');
insert into auto_tap select isnt(public.get_dining_table_context((select qr from auto_context))->>'tableEpoch',(select epoch::text from auto_context),'epoch advances when table freed');
insert into auto_tap select is(pg_temp.auto_order()->>'tableBillId',(select bill::text from auto_context),'old accepted request retries original receipt after epoch changes');
insert into auto_tap select throws_ok($$select pg_temp.auto_order(16,gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'40001','Table round changed. Scan again before ordering.','stale unsubmitted cart cannot open next seating');
insert into auto_tap select is(public.track_table_round((select guest from auto_context))->>'billId',(select bill::text from auto_context),'guest token permanently bound to old bill');
insert into auto_tap select throws_ok($$select pg_temp.auto_order(16,gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'P0001','Shop is not accepting orders.','paused shop cannot auto-open a table');
insert into auto_tap select is((select count(*)::integer from public.table_sessions where shop_id=(select shop from auto_context) and closed_at is null),0,'paused checkout leaves no open round');
insert into auto_tap select lives_ok($$select pg_temp.auto_order(16,gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'new guests open another round automatically');
insert into auto_tap select is((select count(*)::integer from public.table_bills where shop_id=(select shop from auto_context)),2,'second seating has independent bill');
insert into auto_tap select is(public.track_table_round((select guest from auto_context))->>'status','PAID','old guest link remains finished after next seating orders');
insert into auto_tap select * from finish();
